import{_t as e,it as t,n,rt as r}from"./chunks/framework.gd_RGE3V.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireGlu Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireGlu/aireglu-v1-124-0.md","filePath":"aireblock-releases/AireGlu/aireglu-v1-124-0.md","lastUpdated":1792579950000}`),a={name:`aireblock-releases/AireGlu/aireglu-v1-124-0.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="aireglu-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireglu-icon.png"> AireGlu Release Notes</span> <a class="header-anchor" href="#aireglu-release-notes" aria-label="Permalink to “AireGlu Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 1.124.0<br><strong>Release Date:</strong> 21-Oct-2026</p></blockquote><hr><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Target URL persistence issue on logout</li><li>Failure to insert paths and variables into PDF, email and adapter task HTML</li></ul><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Pass original input, output, and transaction details in batch completion callbacks</li><li>Add required-permission options for endpoints secured with OIDC auth</li><li>Allow liquid syntax in task filters</li></ul><hr><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="target-url-persistence-issue-on-logout-glu-3203" tabindex="-1">Target URL persistence issue on logout (GLU-3203) <a class="header-anchor" href="#target-url-persistence-issue-on-logout-glu-3203" aria-label="Permalink to “Target URL persistence issue on logout (GLU-3203)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>A targeted fix ensures that the last viewed page URL is not retained when a user logs out, whether via manual action or token expiry. This prevents navigation errors when a user returns to the application after logging into a new tenant organisation.</p></div><h4 id="failure-to-insert-paths-and-variables-into-pdf-email-and-adapter-task-html-glu-3305" tabindex="-1">Failure to insert paths and variables into PDF, email and adapter task HTML (GLU-3305) <a class="header-anchor" href="#failure-to-insert-paths-and-variables-into-pdf-email-and-adapter-task-html-glu-3305" aria-label="Permalink to “Failure to insert paths and variables into PDF, email and adapter task HTML (GLU-3305)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Secrets, variables, paths, and custom functions which require insertion via clicking the toolbar can now be added to fields marked as &#39;HTML (Raw)&#39; within PDF, email, and adapter tasks. Additionally, the &#39;HTML (Editor)&#39; format now works correctly even if an empty editor is selected prior to insert.</p></div><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="pass-original-input-output-and-transaction-details-in-batch-completion-callbacks-glu-3247" tabindex="-1">Pass original input, output, and transaction details in batch completion callbacks (GLU-3247) <a class="header-anchor" href="#pass-original-input-output-and-transaction-details-in-batch-completion-callbacks-glu-3247" aria-label="Permalink to “Pass original input, output, and transaction details in batch completion callbacks (GLU-3247)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Batch completion callbacks now return the original input for each completed item, the associated endpoint output, and the necessary transaction and correlation identifiers. This facilitates access to data for further processing during endpoint runs, and improved debugging.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>End-to-end visibility is now available for every element in a batch operation. You can see exactly which data was sent in and what was returned for each, making it significantly easier to identify and troubleshoot issues within complex batch runs, as well as to call other endpoints with data at the point of batch completion.</p></div><h4 id="add-required-permission-options-for-endpoints-secured-with-oidc-auth-glu-3209" tabindex="-1">Add required-permission options for endpoints secured with OIDC auth (GLU-3209) <a class="header-anchor" href="#add-required-permission-options-for-endpoints-secured-with-oidc-auth-glu-3209" aria-label="Permalink to “Add required-permission options for endpoints secured with OIDC auth (GLU-3209)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>New configuration fields have been added to endpoints secured with OIDC auth to explicitly specify the target scope for permission checks and the specific permission key required.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now control access to specific tools more granularly. By defining the required scope and permission for an endpoint, you ensure that only users with the correct authorisation can invoke that tool, enhancing security within your workflow configurations. This feature can be used with AireIdentity or custom permissions sources.</p></div><h4 id="allow-liquid-syntax-in-task-filters-glu-888" tabindex="-1">Allow liquid syntax in task filters (GLU-888) <a class="header-anchor" href="#allow-liquid-syntax-in-task-filters-glu-888" aria-label="Permalink to “Allow liquid syntax in task filters (GLU-888)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Task filters have been extended to support Liquid templating syntax. This addition moves beyond the current limitations of JSONPath-based filtering and enables more dynamic and complex filtering logic to be applied to task queries.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now use Liquid to more easily create flexible filtering conditions within your tasks.</p></div>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};